import{_ as o,C as n,o as e,c as s,a2 as l,b as i,w as a,a as d,E,a3 as g}from"./chunks/framework.BODD28Fk.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"건별 납부 관리","description":"","frontmatter":{},"headers":[],"relativePath":"payment/manage.md","filePath":"payment/manage.md","lastUpdated":1793460388000}'),B={name:"payment/manage.md"};function C(h,t,c,_,u,m){const r=n("Mermaid");return e(),s("div",null,[t[1]||(t[1]=l('<h1 id="건별-납부-관리" tabindex="-1">건별 납부 관리 <a class="header-anchor" href="#건별-납부-관리" aria-label="Permalink to &quot;건별 납부 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="개별 계약자 건별 납부 및 약정 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/manage.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>건별 납부 관리</strong> 페이지는 특정 계약자의 전체 분양 대금 납부 일정(약정액)과 실제 통장 수납 내역을 1:1로 정밀 대조하여 미납액을 파악하고, 수납 등록 및 수정, 분할 배정, 그리고 각종 공식 증명서(납부 확인서, 연체료 내역서 등)를 발급하는 수납 상세 카드입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [대금 수납 관리] → [건별 납부 관리]**를 선택하여 접속합니다. (또는 납부 내역 목록에서 계약자 클릭)</li></ul>',4)),(e(),i(g,null,{default:a(()=>[E(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%91%A4%20%EA%B3%84%EC%95%BD%20%EA%B1%B4%20%EC%B0%BE%EA%B8%B0%3Cbr%3E(%EC%84%B1%EB%AA%85%C2%B7%EB%8F%99%ED%98%B8%EC%88%98%C2%B7%EC%9D%BC%EB%A0%A8%EB%B2%88%ED%98%B8%20%EA%B2%80%EC%83%89)%22%5D%20--%3E%20B%5B%22%F0%9F%93%8A%20%EB%82%A9%EB%B6%80%20%EB%8C%80%EC%A1%B0%20%ED%99%94%EB%A9%B4%20%EB%A1%9C%EB%93%9C%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%EC%A2%8C%EC%B8%A1%3A%20%EC%8B%A4%EC%A0%9C%20%EC%88%98%EB%82%A9%20%EA%B4%80%EB%A6%AC%3Cbr%3E(%ED%86%B5%EC%9E%A5%20%EC%9E%85%EA%B8%88%EC%95%A1%20%EB%93%B1%EB%A1%9D%C2%B7%EB%B6%84%ED%95%A0%20%EB%B0%B0%EC%A0%95)%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22%EC%9A%B0%EC%B8%A1%3A%20%EB%82%A9%EB%B6%80%20%ED%98%84%ED%99%A9%20%EB%B3%B4%EB%93%9C%3Cbr%3E(%ED%9A%8C%EC%B0%A8%EB%B3%84%20%EC%95%BD%EC%A0%95%EC%95%A1%20vs%20%EC%88%98%EB%82%A9%EC%95%A1%20%EB%B9%84%EA%B5%90)%22%5D%0A%20%20%20%20C%20%26%20D%20--%3E%20E%5B%22%F0%9F%93%84%20%EA%B3%B5%EC%8B%9D%20%EC%A6%9D%EB%AA%85%EC%84%9C%20%EB%B0%9C%EA%B8%89%3Cbr%3E(%EB%82%A9%EB%B6%80%ED%99%95%EC%9D%B8%EC%84%9C%C2%B7%EC%97%B0%EC%B2%B4%EB%A3%8C%EB%82%B4%EC%97%AD%EC%84%9C%20PDF%20%EC%B6%9C%EB%A0%A5)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-개요-및-화면-2분할-구조" tabindex="-1">1. 개요 및 화면 2분할 구조 <a class="header-anchor" href="#_1-개요-및-화면-2분할-구조" aria-label="Permalink to &quot;1. 개요 및 화면 2분할 구조&quot;">​</a></h2><p>선택된 계약자의 전체 분양 대금 납부 계획(약정액)과 실제 수납 실적을 한 화면에서 비교 검토합니다.</p><ul><li><strong>좌측 영역 (실제 수납 내역 관리)</strong>: 실제로 통장에 입금된 건별 거래 내역을 등록, 수정, 삭제하거나 여러 회차로 분할 배정합니다.</li><li><strong>우측 영역 (납부 현황 보드)</strong>: 계약서상 회차별 약정 기일과 약정 금액, 기납부액 및 미납·과오납 상태를 실시간 대조합니다.</li></ul><h2 id="_2-주요-기능" tabindex="-1">2. 주요 기능 <a class="header-anchor" href="#_2-주요-기능" aria-label="Permalink to &quot;2. 주요 기능&quot;">​</a></h2><ul><li><strong>계약자 검색 및 상세 수납 정보 로드</strong>: 성명, 일련번호, 동호수 검색</li><li><strong>회차별 납부 약정 현황 실시간 대조</strong>: 약정일, 약정금액, 수납금액, 미납액(빨간색), 과오납(파란색) 표출</li><li><strong>개별 수납 내역 등록 및 다회차 분할 배정</strong>: 1건의 입금액을 2차 계약금과 업무대행비 등으로 나누어 배정</li><li><strong>금액 일치 검증</strong>: 통장 실제 입금액과 회차별 분할 금액의 합계가 100% 일치하도록 시스템 강제 검증</li><li><strong>공식 대외 증명서 원클릭 PDF 발급</strong>: 납부 확인서(일반용/확인용), 일자별 연체료 산출 내역서, 선납할인/연체가산금 내역서</li></ul><h2 id="_3-화면-구성-및-상세-조작법" tabindex="-1">3. 화면 구성 및 상세 조작법 <a class="header-anchor" href="#_3-화면-구성-및-상세-조작법" aria-label="Permalink to &quot;3. 화면 구성 및 상세 조작법&quot;">​</a></h2><h3 id="_1-계약-건-찾기" tabindex="-1">1. 계약 건 찾기 <a class="header-anchor" href="#_1-계약-건-찾기" aria-label="Permalink to &quot;1. 계약 건 찾기&quot;">​</a></h3><ul><li>상단 검색창에 계약자 성명이나 동호수, 일련번호를 입력하고 <code>[계약 건 찾기]</code>를 누르면 하단에 매칭 버튼이 나열됩니다.</li><li>해당 버튼을 클릭하면 계약자의 동호수, 평형 타입, 총 공급가 정보와 함께 전체 납부 내역이 즉시 로드됩니다.</li></ul><h3 id="_2-우측-납부-현황-보드-약정-대조표" tabindex="-1">2. 우측: 납부 현황 보드 (약정 대조표) <a class="header-anchor" href="#_2-우측-납부-현황-보드-약정-대조표" aria-label="Permalink to &quot;2. 우측: 납부 현황 보드 (약정 대조표)&quot;">​</a></h3><p>해당 계약자의 계약 조건에 따른 전체 납부 계획과 현재까지의 성과를 실시간으로 비교하여 보여줍니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>납부기일</strong></td><td style="text-align:left;">각 회차별 납부 약정일 (계약일 및 설정된 경과일수 기반 자동 산출)</td></tr><tr><td style="text-align:left;"><strong>구분</strong></td><td style="text-align:left;">납부 회차 명칭 (계약금, 중도금 1~6회차, 잔금 등)</td></tr><tr><td style="text-align:left;"><strong>약정금액</strong></td><td style="text-align:left;"><a href="/project/settings.html">분양 조건 설정</a>에 따라 산출된 회차별 필수 납부 금액</td></tr><tr><td style="text-align:left;"><strong>수납금액</strong></td><td style="text-align:left;">실제로 입금되어 해당 회차에 배정 완료된 금액의 합계</td></tr><tr><td style="text-align:left;"><strong>미(과오)납</strong></td><td style="text-align:left;"><code>[수납금액 - 약정금액]</code> 결과.<br>• <strong>음수(빨간색)</strong>: 납부 기한이 지났으나 덜 낸 <strong>미납금</strong><br>• <strong>양수(파란색)</strong>: 약정액보다 더 많이 낸 <strong>과오납(초과 입금)</strong></td></tr></tbody></table><h3 id="_3-좌측-실제-수납-내역-관리-입금-처리" tabindex="-1">3. 좌측: 실제 수납 내역 관리 (입금 처리) <a class="header-anchor" href="#_3-좌측-실제-수납-내역-관리-입금-처리" aria-label="Permalink to &quot;3. 좌측: 실제 수납 내역 관리 (입금 처리)&quot;">​</a></h3><ul><li><strong>신규 납부 등록</strong>: 새로운 통장 입금 건을 수동으로 추가 등록합니다.</li><li><strong>수정 및 확인</strong>: 목록의 금액이나 <code>[보기]</code> 버튼을 클릭하여 입금 일자나 회차 배정 내역을 수정합니다.</li><li><strong>차수 분할 등록 (중요)</strong>: <ul><li>예: 계약자가 2,000만 원을 한 번에 입금한 경우, 이를 <code>[2차 계약금 1,000만 원] + [업무대행비 1,000만 원]</code>으로 분할하여 각각의 회차에 정확하게 배정할 수 있습니다.</li></ul></li><li><strong>계약 건 변경 (오입금 원복)</strong>: 다른 동호수의 입금 건을 잘못 매핑한 경우, 해당 수납 내역을 현재 계약자에게서 분리하여 [납부 내역 관리] 목록으로 되돌립니다.</li></ul><h3 id="_4-납부-확인서-및-공식-증명서-발급" tabindex="-1">4. 납부 확인서 및 공식 증명서 발급 <a class="header-anchor" href="#_4-납부-확인서-및-공식-증명서-발급" aria-label="Permalink to &quot;4. 납부 확인서 및 공식 증명서 발급&quot;">​</a></h3><p>우측 상단의 증명서 발급 버튼을 통해 표준 A4 규격의 공식 문서를 즉시 출력할 수 있습니다:</p><table tabindex="0"><thead><tr><th style="text-align:left;">증명서 종류</th><th style="text-align:left;">상세 설명 및 실무 용도</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>납부 확인서 (일반용)</strong></td><td style="text-align:left;">미납 내역 및 연체/가산금 정보가 상세히 표기된 종합 확인서 (사내 채권 관리 및 계약자 안내용)</td></tr><tr><td style="text-align:left;"><strong>납부 확인서 (확인용)</strong></td><td style="text-align:left;">연체나 미납 표기 없이 <strong>실제로 정상 수납 완료된 내역만 깨끗하게 인쇄</strong>되는 대외 제출용 확인서 (은행 대출 연장, 세무서 소득공제 증빙용)</td></tr><tr><td style="text-align:left;"><strong>일자별 연체료 내역서</strong></td><td style="text-align:left;">납부 약정일 대비 입금 지연 일수 및 적용 이율에 따른 상세 연체료 산출 근거표</td></tr><tr><td style="text-align:left;"><strong>할인/가산금 내역서</strong></td><td style="text-align:left;">중도금 선납 할인액과 연체가산금을 종합 정산한 공식 내역서</td></tr></tbody></table><h2 id="_4-💡-주요-관리-포인트-및-실무-가이드" tabindex="-1">4. 💡 주요 관리 포인트 및 실무 가이드 <a class="header-anchor" href="#_4-💡-주요-관리-포인트-및-실무-가이드" aria-label="Permalink to &quot;4. 💡 주요 관리 포인트 및 실무 가이드&quot;">​</a></h2><ul><li><strong>금액 일치 자동 검증 로직</strong>: <ul><li>수납 등록 시 **[은행 실제 입금액]**과 하단의 **[회차별 분할 배정 금액의 합계]**가 1원 단위까지 완벽히 일치해야만 저장이 완료됩니다. 차액이 발생하면 시스템이 경고 메시지를 표출하여 장부 불일치 사고를 원천 방지합니다.</li></ul></li><li><strong>데이터 무결성을 위한 90일 수정 제한 규칙</strong>: <ul><li>회계 결산 및 감사 무결성을 위해, 수납일(거래일)로부터 <strong>90일이 경과한 과거 수납 데이터</strong>는 일반 권한으로 임의 수정이나 삭제가 전면 금지됩니다. 부득이한 수정이 필요한 경우 최고 관리자 권한을 통해 처리해야 합니다.</li></ul></li></ul>',18))])}const x=o(B,[["render",C]]);export{b as __pageData,x as default};
